41	const PROCESSING_FEE = 5;
42	const FIRST_INSURANCE_SURCHARGE = 0.1;
43	
44	const BASE_PREMIUMS = {
45	  sword: 100,
46	  amulet: 60,
47	  staff: 80,
48	  potion: 40,
49	  rune: 25,
50	  moonstone: 25,
51	} as const satisfies Record<string, number>;
52	
53	type KnownItemType = keyof typeof BASE_PREMIUMS;
54	
55	const basePremiumOf = (itemType: string): number => BASE_PREMIUMS[itemType as KnownItemType];
56	
57	const BLOCK_SIZE = 3;
58	const BLOCK_PREMIUM = 60;
59	
60	const countsByType = (items: Item[]): Map<string, number> => {
61	  const counts = new Map<string, number>();
62	  for (const item of items) counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
63	  return counts;
64	};
65	
66	const basePremiumForGroup = (itemType: string, count: number): number => {
67	  if (count === BLOCK_SIZE) return BLOCK_PREMIUM;
68	  return count * basePremiumOf(itemType);
69	};
70	
71	const policyBasePremiumOf = (items: Item[]): number =>
72	  [...countsByType(items)].reduce(
73	    (total, [itemType, count]) => total + basePremiumForGroup(itemType, count),
74	    0,
75	  );
76	
77	const CURSE_SURCHARGE = 0.5;
78	
79	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
80	const HIGH_ENCHANTMENT_THRESHOLD = 5;
81	
82	const itemSurchargeRateOf = (item: Item): number => {
83	  const curse = item.cursed ? CURSE_SURCHARGE : 0;
84	  const enchantment =
85	    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD ? HIGH_ENCHANTMENT_SURCHARGE : 0;
86	  return curse + enchantment;
87	};
88	
89	const itemSurchargesOf = (items: Item[]): number =>
90	  items.reduce((total, item) => total + basePremiumOf(item.type) * itemSurchargeRateOf(item), 0);
91	
92	const LOYALTY_DISCOUNT = 0.2;
93	const LOYALTY_THRESHOLD_YEARS = 2;
94	
95	// Customer-derived share of the policy-scoped rate. Other policy-scoped
96	// modifiers (e.g. the follow-up contract discount, which depends on a step's
97	// position in the scenario rather than on the customer) belong alongside this
98	// one, not inside it.
99	const customerModifierRateOf = (customer: Customer): number => {
100	  const loyalty = customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS ? -LOYALTY_DISCOUNT : 0;
101	  return FIRST_INSURANCE_SURCHARGE + loyalty;
102	};
103	
104	const FOLLOW_UP_DISCOUNT = 0.15;
105	
106	// `contractOrdinal` is zero-based: the customer's first contract in the
107	// scenario is 0 and carries no follow-up discount.
108	const policyModifierRateOf = (customer: Customer, contractOrdinal: number): number => {
109	  const followUp = contractOrdinal > 0 ? -FOLLOW_UP_DISCOUNT : 0;
110	  return customerModifierRateOf(customer) + followUp;
111	};
112	
113	const premiumFor = (quote: QuoteStep, customer: Customer, contractOrdinal: number): number => {
114	  const policyBase = policyBasePremiumOf(quote.items);
115	  // Policy-scoped modifiers apply to the policy base only; item-scoped
116	  // surcharges are added afterwards and never widen that base.
117	  const policyModifiers = policyBase * policyModifierRateOf(customer, contractOrdinal);
118	  return Math.ceil(
119	    policyBase + itemSurchargesOf(quote.items) + policyModifiers + PROCESSING_FEE,
120	  );
121	};
122	
123	export const runScenario = (scenario: Scenario): ScenarioResult => {
124	  let contractOrdinal = 0;
125	  const results = scenario.steps.map((step) => {
126	    if (step.op !== "quote") throw new Error(`unsupported step: ${step.op}`);
127	    return { premium: premiumFor(step, scenario.customer, contractOrdinal++) };
128	  });
129	  return { results };
130	};
